class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("pop from an empty stack")
        return self._items.pop()

    def peek(self):
        return self._items[-1] if self._items else None

    def __len__(self):
        return len(self._items)

history = Stack()
for page in ["home", "search", "product", "cart"]:
    history.push(page)

print("Back from", history.pop(), "to", history.peek())
print("Back from", history.pop(), "to", history.peek())
print(len(history), "pages left")

