def bracket_error(code):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []          # holds (index, bracket) for each open bracket
    for i, ch in enumerate(code):
        if ch in "([{":
            stack.append((i, ch))
        elif ch in pairs:
            if not stack or stack[-1][1] != pairs[ch]:
                return i
            stack.pop()
    if stack:
        return stack[-1][0]
    return None

print(bracket_error("print(len([1, 2]))"))   # None
print(bracket_error("print((1, 2)"))         # 5

