class Node:
    def __init__(self, value, next_node=None):
        self.value = value
        self.next = next_node

class Playlist:
    def __init__(self, songs=()):
        self.head = None
        for song in reversed(songs):
            self.head = Node(song, self.head)

    def __iter__(self):
        node = self.head
        while node:
            yield node.value
            node = node.next

    def reverse(self):
        prev, node = None, self.head
        while node:
            nxt = node.next      # remember the rest of the list
            node.next = prev     # flip this link
            prev, node = node, nxt
        self.head = prev

p = Playlist(["A", "B", "C"])
p.reverse()
print(list(p))   # ['C', 'B', 'A']

