class HashMap:
    def __init__(self, size=5):
        self.buckets = [[] for _ in range(size)]

    def _index(self, key):
        h = 0
        for ch in key:                  # a simple, repeatable string hash
            h = h * 31 + ord(ch)
        return h % len(self.buckets)

    def put(self, key, value):
        bucket = self.buckets[self._index(key)]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)    # existing key: update it
                return
        bucket.append((key, value))         # new key: add a pair

    def get(self, key, default=None):
        for k, v in self.buckets[self._index(key)]:
            if k == key:
                return v
        return default

menu = HashMap()
for item, price in [("chai", 20), ("dosa", 60), ("idli", 40), ("vada", 30), ("upma", 35), ("chai", 25)]:
    menu.put(item, price)
print(menu.get("chai"), menu.get("idli"), menu.get("pizza", "not on menu"))
for i, bucket in enumerate(menu.buckets):
    print(i, bucket)
